#!/usr/bin/env python3
"""
Round 110b (culprits), 29 September 2026. Needs round 109b.

Climate TRACE by gas read from culprits-tiles-gases.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = "## Round 110b (29 September)\n\nNeeds round 109b. Tiles patch round110b_tiles.py beside it, and a new\nrepository, culprits-tiles-gases, whose one file is .github/workflows/build.yml.\n\n- culprits-tiles-more reached 11 GB and GitHub Pages stopped publishing it\n  (limit 10 GB). The Climate TRACE by-gas archives (co2/ch4/n2o, 5.6 GB) move\n  to culprits-tiles-gases: CT_GASES_BASE points there; NEO_COPY stays on\n  culprits-tiles-more. That repo's workflow runs culprits-tiles-more's\n  gases/run.sh: seed (copies the archives from tiles-more at 64ba5fd, once),\n  then ct_gases, ct_gases_ch4, ct_gases_n2o daily.\n- Script version app.js?v=1001.\n\n"
HEAD = "## Round 110b (29 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round110b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 109b" not in text:
        sys.exit("round110b: round 109b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round110b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round110b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round110b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 109b")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
